+{% assign member = include.member %}
+<div class = "container" id="{{member.name | slugify}}">
+  <!-- Avatar starts-->
+  <div class="avatar">
+    {% if member.avatar %}
+        <div class="author__avatar">
+            {% if member.avatar contains "://" %}
+                {% assign member_src = member.avatar %}
+            {% else %}
+                {% assign member_src = member.avatar | absolute_url %}
+            {% endif %}
+            {% if member.uri %}
+                {% if member.uri contains "://" %}
+                    {% assign member_link = member.uri %}
+                {% else %}
+                    {% assign member_link = member.uri | absolute_url %}
+                {% endif %}
+                <a href="{{ member_link }}">
+                    <img src="{{ member_src }}" alt="{{ member.name }}">
+                </a>
+            {% else %}
+                <img src="{{ member_src }}" alt="{{ member.name }}">
+            {% endif %}
+        </div>
+    {% endif %}
+    </div>
+    <!-- Avatar ends-->
+    <div class="member-details">
+    <div class="author__content">
+        {% if member.uri %}
+        <a href="{{ member_link }}"><h3 class="author__name" itemprop="name">{{ member.name }}</h3></a>
+        {% else %}
+        <h3 class="author__name" itemprop="name">{{ member.name }}</h3>
+        {% endif %}
+
+        {% if member.bio %}
+        <p class="author__bio" itemprop="description">
+            {{ member.bio }}
+        </p>
+        {% endif %}
+        <p class="location">
+        {% if member.location %}<!-- member location --><i class="fas fa-fw fa-map-marker-alt"></i> {{ member.location }}<br>{% endif %}
+        </p>
+    </div>
+    <!-- </"author__content"> -->
+    <div class="social-icons">
+        {% if member.uri %}<!-- member website --><a href="{{ member.uri }}"><i class="fas fa-fw fa-link"></i></a>{% endif %}
+        {% if member.email %}<!-- member email --><a href="mailto:{{ member.email }}"><meta itemprop="email" content="{{ member.email }}" /><i class="fas fa-fw fa-envelope-square" aria-hidden="true"></i></a>{% endif %}
+        {% if member.linkedin %}<!-- member linkedin --><a href="https://www.linkedin.com/in/{{ member.linkedin }}"><i class="fab fa-fw fa-linkedin"></i></a>{% endif %}
+        {% if member.github %}<!-- member github --><a href="https://github.com/{{ member.github }}"><i class="fab fa-fw fa-github"></i></a>{% endif %}
+        {% if member.twitter %}<!-- member twitter --><a href="https://twitter.com/{{ member.twitter }}"><i class="fab fa-fw fa-twitter-square"></i></a>{% endif %}
+    </div><!-- /social-icons -->
+    </div>
+
+</div>

@@ -0,0 +1,37 @@
+{% if post.header.teaser %}
+  {% capture teaser %}{{ post.header.teaser }}{% endcapture %}
+{% else %}
+  {% assign teaser = site.teaser %}
+{% endif %}
+
+{% if post.id %}
+  {% assign title = post.title | markdownify | remove: "<p>" | remove: "</p>" %}
+{% else %}
+  {% assign title = post.title %}
+{% endif %}
+
+<div class="{{ include.type | default: "list" }}__item">
+  <article class="archive__item" itemscope itemtype="http://schema.org/CreativeWork">
+    {% if include.type == "grid" and teaser %}
+      <div class="archive__item-teaser">
+        <img src=
+          {% if teaser contains "://" %}
+            "{{ teaser }}"
+          {% else %}
+            "{{ teaser | relative_url }}"
+          {% endif %}
+          alt="">
+      </div>
+    {% endif %}
+    <h2 class="archive__item-title" itemprop="headline">
+      {% if post.link %}
+        <a href="{{ post.link }}">{{ title }}</a> <a href="{{ post.url | relative_url }}" rel="permalink"><i class="fas fa-link" aria-hidden="true" title="permalink"></i><span class="sr-only">Permalink</span></a>
+      {% else %}
+        <a href="{{ post.url | relative_url }}" rel="permalink">{{ title }}</a>
+      {% endif %}
+    </h2>
+    {% if post.read_time %}
+      <p class="page__meta"><i class="far fa-clock" aria-hidden="true"></i> {% include read-time.html %}</p>
+    {% endif %}
+  </article>
+</div>

