+.timeline{
+    display: flex;
+    height: 300px;
+    width: 100%;
+    > div{
+        display: flex;
+        align-items: center;
+    }
+    img {
+        width: 120px;
+        padding: 5px;
+    }
+    .event{
+      position: relative;
+      direction: ltr;
+      .event_bubble{
+          display: flex;
+          position: absolute;
+          background-color: #e1e1e1;
+          border-radius: 5px;
+          width: 240px;
+          height: 80px;
+          box-shadow: inset 0 0 5px rgba(158, 158, 158, 0.64);
+          .logo {
+              width: 400px;
+          }
+          .event_title {
+            font-size: 14px;
+            align-items: center;
+            margin-left: 12px;
+            margin-top: 3px;
+            padding: 5px;
+            overflow: auto;
+            height: 70px;
+            a {
+                text-decoration: none;
+                color: #000;
+            }
+          }
+          .event_description {
+              font-size: 11px;
+          }
+
+      }
+      .time{
+          font-size: 12px;
+          margin-top: -16px;
+          padding-top: 5px;
+          margin-left: -5px;
+      }
+    }
+    .event_bubble:before {
+      content: "";
+      position: absolute;
+      width: 0;
+      height: 0;
+      border-style: solid;
+      border-color: transparent;
+      border-bottom: 0;
+    }
+}
+
+.timeline > div:nth-of-type(even) .event .event_bubble {
+  top: -85px;
+  left: -15px;
+}
+
+.timeline > div:nth-of-type(odd) .event .event_bubble {
+  left: -105px;
+  top: 33px;
+}
+
+.timeline > div:nth-of-type(odd) .event .time{
