+    margin-top: -46px;
+    margin-left: -9px;
+    padding-bottom: 13px;
+    padding-left: 5px;
+}
+
+.timeline > div:nth-of-type(even) .event .event_bubble:before {
+  bottom: -10px;
+  left: 13px;
+  border-top-color: #e1e1e1;
+  border-width: 12px;
+}
+
+.timeline > div:nth-of-type(odd) .event_bubble:before {
